// Prediction runtime oracle test.
//
// Replays libs/prediction/prediction_tests/fixtures/prediction_runtime_oracle.json
// (generated by tools/oracle/generate_prediction_runtime_fixtures.py, whose
// golden outputs come from the REAL Python production tiled inference through
// the REAL onnxruntime CPU session) against the native C++ runtime:
//
//   load model package -> validate input -> ONNX tiled inference ->
//   center-crop fusion -> summary -> spatial result + provenance envelope
//
// Every success case compares the written classmap bytes, the float16
// probability bits (1 fp16 ulp tolerance for the numpy/std::exp boundary),
// the deterministic summary and the spatial validator outcome. Error cases
// assert the C++ error class + a message fragment. C++-only cases cover
// cancellation + resume, deterministic repeats, the task service and the
// workflow-node adapter.
//
// The native path never calls Python: this file is the replay side.

#include <pwb/prediction/integration_seams.hpp>
#include <pwb/prediction/onnx_session.hpp>
#include <pwb/prediction/prediction_pipeline.hpp>
#include <pwb/prediction/prediction_service.hpp>
#include <pwb/prediction/spatial_result.hpp>

#include <pwb/domain/json.hpp>
#include <pwb/domain/sha256.hpp>

#include <algorithm>
#include <atomic>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <future>
#include <iostream>
#include <iterator>
#include <mutex>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>

#ifndef PWB_RUNTIME_FIXTURE
#error "PWB_RUNTIME_FIXTURE must point at prediction_runtime_oracle.json"
#endif

namespace {

namespace fs = std::filesystem;
using pwb::domain::Json;
using namespace pwb::prediction;

int g_failures = 0;
int g_checks = 0;

void check(bool ok, const std::string& what) {
    ++g_checks;
    if (!ok) {
        ++g_failures;
        std::cerr << "FAIL: " << what << "\n";
    }
}

const fs::path& fixture_json() {
    static const fs::path path(PWB_RUNTIME_FIXTURE);
    return path;
}

const fs::path& fixture_root() {
    static const fs::path root = fixture_json().parent_path() / "prediction_runtime";
    return root;
}

Json load_fixture() {
    std::ifstream stream(fixture_json(), std::ios::binary);
    if (!stream) {
        throw std::runtime_error("cannot open fixture " +
                                 fixture_json().string());
    }
    Json data;
    stream >> data;
    return data;
}

std::string read_text(const fs::path& path) {
    std::ifstream stream(path, std::ios::binary);
    return std::string((std::istreambuf_iterator<char>(stream)),
                       std::istreambuf_iterator<char>());
}

std::vector<std::uint8_t> read_bytes(const fs::path& path) {
    std::ifstream stream(path, std::ios::binary);
    return std::vector<std::uint8_t>((std::istreambuf_iterator<char>(stream)),
                                     std::istreambuf_iterator<char>());
}

std::vector<std::uint16_t> read_u16(const fs::path& path) {
    const std::vector<std::uint8_t> bytes = read_bytes(path);
    std::vector<std::uint16_t> values(bytes.size() / 2);
    std::memcpy(values.data(), bytes.data(), values.size() * 2);
    return values;
}

fs::path prepare_dir(const std::string& name) {
    const fs::path dir = fs::temp_directory_path() / ("pwb-prediction-" + name);
    std::error_code ec;
    fs::remove_all(dir, ec);
    fs::create_directories(dir, ec);
    return dir;
}

// Independent binary16 decoder (deliberately NOT the library helper): the
// golden comparison must not be able to hide a bug in the code under test.
float test_half_to_float(std::uint16_t bits) {
    const int sign = (bits >> 15) & 1;
    const int exponent = (bits >> 10) & 0x1f;
    const int mantissa = bits & 0x3ff;
    double value = 0.0;
    if (exponent == 0) {
        value = std::ldexp(static_cast<double>(mantissa), -24);
    } else if (exponent == 31) {
        if (mantissa != 0) return std::numeric_limits<float>::quiet_NaN();
        return sign != 0 ? -std::numeric_limits<float>::infinity()
                         : std::numeric_limits<float>::infinity();
    } else {
        value = std::ldexp(1.0 + static_cast<double>(mantissa) / 1024.0,
                           exponent - 15);
    }
    return static_cast<float>(sign != 0 ? -value : value);
}

double fp16_ulp(double want) {
    const double value = std::abs(want);
    if (value == 0.0) return std::ldexp(1.0, -24);
    if (!std::isfinite(value)) return 0.0;
    int exponent = 0;
    std::frexp(value, &exponent);
    if (value < std::ldexp(1.0, -14)) return std::ldexp(1.0, -24);
    return std::ldexp(1.0, exponent - 11);
}

bool same_probability(double got, double want) {
    if (std::isnan(want)) return std::isnan(got);
    if (std::isinf(want)) return got == want;
    return std::abs(got - want) <= fp16_ulp(want) + 1e-12;
}

// nlohmann parses positive JSON integers as number_unsigned while the C++
// runtime builds them as number_integer; the semantic comparator treats the
// two as different types, so canonicalize integer nodes before comparing.
Json normalize_integers(const Json& value) {
    if (value.is_number_unsigned()) {
        return Json(static_cast<long long>(value.get<unsigned long long>()));
    }
    if (value.is_object()) {
        Json out = Json::object();
        for (auto it = value.begin(); it != value.end(); ++it) {
            out[it.key()] = normalize_integers(it.value());
        }
        return out;
    }
    if (value.is_array()) {
        Json out = Json::array();
        for (const Json& item : value) {
            out.push_back(normalize_integers(item));
        }
        return out;
    }
    return value;
}

bool semantically_equal(const Json& left, const Json& right) {
    return pwb::domain::json_semantically_equal(normalize_integers(left),
                                                normalize_integers(right));
}

std::string error_class_name(const std::exception& exc) {
    if (dynamic_cast<const ModelPackageError*>(&exc) != nullptr) {
        return "ModelPackageError";
    }
    if (dynamic_cast<const InputContractError*>(&exc) != nullptr) {
        return "InputContractError";
    }
    if (dynamic_cast<const TiledInferenceError*>(&exc) != nullptr) {
        return "TiledInferenceError";
    }
    if (dynamic_cast<const UnicodeDecodeError*>(&exc) != nullptr) {
        return "UnicodeDecodeError";
    }
    if (dynamic_cast<const pwb::prediction::ValueError*>(&exc) != nullptr) {
        return "ValueError";
    }
    if (dynamic_cast<const pwb::prediction::TypeError*>(&exc) != nullptr) {
        return "TypeError";
    }
    if (dynamic_cast<const pwb::prediction::AttributeError*>(&exc) != nullptr) {
        return "AttributeError";
    }
    return "std::exception";
}

Json absolutize_input(const Json& input) {
    Json out = input;
    const auto uri = out.find("uri");
    if (uri != out.end() && uri->is_string() && !uri->get<std::string>().empty()) {
        out["uri"] = (fixture_root() / uri->get<std::string>()).string();
    }
    const auto mask = out.find("quality_mask_uri");
    if (mask != out.end() && mask->is_string()
        && !mask->get<std::string>().empty()) {
        out["quality_mask_uri"] =
            (fixture_root() / mask->get<std::string>()).string();
    }
    return out;
}

Json task_parameters(const Json& test_case, const fs::path& output_dir,
                     bool write_outputs) {
    Json options = test_case.contains("options") ? test_case["options"]
                                                 : Json::object();
    options["output_dir"] = output_dir.string();
    options["write_outputs"] = write_outputs;
    Json parameters = Json::object();
    parameters["manifest_path"] =
        (fixture_root() / test_case["package"].get<std::string>()).string();
    parameters["input"] = absolutize_input(test_case["input"]);
    parameters["options"] = std::move(options);
    parameters["run_id"] = "fixture-" + test_case["id"].get<std::string>();
    return parameters;
}

void compare_summary(const Json& expected, const Json& actual,
                     const std::string& case_id) {
    const auto same_key = [&](const char* key) {
        const bool has_expected = expected.contains(key);
        const bool has_actual = actual.contains(key);
        check(has_expected == has_actual,
              case_id + ": summary key " + key + " presence");
        if (!has_expected || !has_actual) return;
        const Json& want = expected[key];
        const Json& got = actual[key];
        if (std::string(key) == "mean_confidence") {
            if (want.is_null() || got.is_null()) {
                check(want.is_null() && got.is_null(),
                      case_id + ": mean_confidence nullness");
            } else {
                const double w = want.get<double>();
                const double g = got.get<double>();
                check(std::abs(w - g) <= 1e-9 * std::max(1.0, std::abs(w)),
                      case_id + ": mean_confidence " + std::to_string(g)
                          + " vs " + std::to_string(w));
            }
            return;
        }
        check(semantically_equal(want, got),
              case_id + ": summary key " + key + " mismatch");
    };
    for (const char* key :
         {"summary_version", "classes", "class_names", "voxels_total",
          "voxels_nodata", "class_counts", "out_of_range_class_count",
          "probmap_stored", "voxels_scored", "nan_confidence_count",
          "mean_confidence", "min_confidence", "max_confidence",
          "confidence_histogram", "confidence_histogram_bins"}) {
        same_key(key);
    }
}

void compare_classmap(const Json& expected, const std::vector<std::uint8_t>& got,
                      const std::string& case_id) {
    check(expected.size() == got.size(), case_id + ": classmap size");
    if (expected.size() != got.size()) return;
    std::size_t mismatches = 0;
    std::size_t first = 0;
    for (std::size_t i = 0; i < got.size(); ++i) {
        if (expected[i].get<int>() != static_cast<int>(got[i])) {
            if (mismatches == 0) first = i;
            ++mismatches;
        }
    }
    check(mismatches == 0,
          case_id + ": classmap mismatches=" + std::to_string(mismatches)
              + " first=" + std::to_string(first));
}

std::size_t probmap_mismatches(const Json& expected,
                               const std::vector<std::uint16_t>& got,
                               double* worst) {
    *worst = 0.0;
    if (expected.size() != got.size()) return expected.size() + got.size() + 1;
    std::size_t mismatches = 0;
    for (std::size_t i = 0; i < got.size(); ++i) {
        const double want = static_cast<double>(test_half_to_float(
            static_cast<std::uint16_t>(expected[i].get<int>())));
        const double have =
            static_cast<double>(test_half_to_float(got[i]));
        if (!same_probability(have, want)) {
            ++mismatches;
            *worst = std::max(*worst, std::abs(have - want));
        }
    }
    return mismatches;
}

void compare_probmap(const Json& expected,
                     const std::vector<std::uint16_t>& got,
                     const std::string& case_id) {
    double worst = 0.0;
    const std::size_t mismatches = probmap_mismatches(expected, got, &worst);
    check(mismatches == 0,
          case_id + ": probmap mismatches=" + std::to_string(mismatches)
              + " worst=" + std::to_string(worst));
}

// Negative self-check: the comparator must actually reject a perturbed
// probability map (otherwise every probmap comparison above is vacuous).
void run_comparator_self_check(const Json& baseline) {
    const Json& expected = baseline["expect"]["probmap_bits"];
    std::vector<std::uint16_t> golden(expected.size());
    for (std::size_t i = 0; i < expected.size(); ++i) {
        golden[i] = static_cast<std::uint16_t>(expected[i].get<int>());
    }
    double worst = 0.0;
    check(probmap_mismatches(expected, golden, &worst) == 0,
          "comparator self-check: identical maps pass");
    std::vector<std::uint16_t> perturbed = golden;
    std::size_t index = 0;
    while (index < perturbed.size()) {
        const std::uint16_t bits = perturbed[index];
        const int exponent = (bits >> 10) & 0x1f;
        const double value =
            static_cast<double>(test_half_to_float(bits));
        if (exponent > 0 && exponent < 24 && value >= 0.25 && value <= 0.75) {
            break;
        }
        ++index;
    }
    check(index < perturbed.size(), "comparator self-check: mutable sample");
    if (index < perturbed.size()) {
        // One exponent step: far beyond the 1-fp16-ulp tolerance, so the
        // comparator must reject it.
        perturbed[index] =
            static_cast<std::uint16_t>(perturbed[index] ^ 0x0400);
        check(probmap_mismatches(expected, perturbed, &worst) >= 1,
              "comparator self-check: a perturbed probability is rejected");
    }
    check(test_half_to_float(0x3800) == 0.5f, "half decoder: 0.5");
    check(test_half_to_float(0x3C00) == 1.0f, "half decoder: 1.0");
    check(test_half_to_float(0x0001) == std::ldexp(1.0f, -24),
          "half decoder: minimum subnormal");
    check(std::isinf(test_half_to_float(0x7C00)), "half decoder: +inf");
    check(std::isnan(test_half_to_float(0x7E00)), "half decoder: NaN");
}

void run_success_case(const Json& test_case) {
    const std::string case_id = test_case["id"].get<std::string>();
    const Json& expect = test_case["expect"];
    const fs::path output_dir = prepare_dir(case_id);
    const Json parameters = task_parameters(test_case, output_dir, true);

    PredictionTaskRuntime runtime(prediction_task_request_from_json(parameters));
    const Json validation = runtime.validate();
    check(validation.empty(),
          case_id + ": validate() must be clean, got " + validation.dump());

    const PredictionTaskResult result = runtime.execute();
    check(result.status == PredictionTaskStatus::Succeeded,
          case_id + ": status succeeded");
    check(result.outputs_written, case_id + ": outputs written");

    const Json& stats = expect["stats"];
    check(result.stats.tiles_total == stats["tiles_total"].get<int>(),
          case_id + ": tiles_total");
    check(result.stats.tiles_done == stats["tiles_done"].get<int>(),
          case_id + ": tiles_done");
    check(result.stats.cancelled == stats["cancelled"].get<bool>(),
          case_id + ": cancelled");
    check(result.stats.classes == stats["classes"].get<int>(),
          case_id + ": classes");
    check(result.stats.overlap == stats["overlap"].get<int>(),
          case_id + ": overlap");
    check(result.stats.batch == stats["batch"].get<int>(),
          case_id + ": batch");
    check(result.stats.mode == stats["device_mode"].get<std::string>(),
          case_id + ": device_mode");

    compare_summary(expect["summary"], result.summary, case_id);

    const std::vector<std::uint8_t> classmap = read_bytes(result.paths.classmap);
    compare_classmap(expect["classmap"], classmap, case_id);
    std::vector<std::uint16_t> probmap;
    if (expect.value("probmap_absent", false)) {
        check(result.paths.probmap.empty(), case_id + ": probmap not persisted");
        check(!fs::exists(output_dir / "probmap.raw"),
              case_id + ": no probmap.raw on disk");
        check(!result.summary["probmap_stored"].get<bool>(),
              case_id + ": summary reports probmap_stored=false");
    } else {
        probmap = read_u16(result.paths.probmap);
        compare_probmap(expect["probmap_bits"], probmap, case_id);
    }

    // Artifact integrity: the descriptor's digests describe the bytes on disk.
    const Json& descriptor = result.output_descriptor;
    check(descriptor["classmap_bytes"].get<long long>()
              == static_cast<long long>(classmap.size()),
          case_id + ": descriptor classmap_bytes");
    check(descriptor["classmap_sha256"].get<std::string>()
              == pwb::domain::Sha256::of_file(result.paths.classmap).value_or(""),
          case_id + ": descriptor classmap sha256");
    if (!result.paths.probmap.empty()) {
        check(descriptor["probmap_sha256"].get<std::string>()
                  == pwb::domain::Sha256::of_file(result.paths.probmap)
                         .value_or(""),
              case_id + ": descriptor probmap sha256");
    }

    // Spatial envelope must satisfy the frozen spatial contract.
    const Json spatial_errors =
        validate_spatial_result(result.spatial_result, Json(), false);
    check(semantically_equal(spatial_errors,
                                               expect["validate_errors"]),
          case_id + ": spatial validator errors "
              + spatial_errors.dump() + " expected "
              + expect["validate_errors"].dump());
    check(spatial_type_of(result.spatial_result)
              == expect["spatial_type"].get<std::string>(),
          case_id + ": spatial type");
    const Json bounded = bounded_result_summary(result.spatial_result);
    check(bounded["spatial"]["grid_omitted"].get<bool>(),
          case_id + ": bounded summary strips the grid");

    // Provenance binds the executed bytes and the input descriptor.
    check(result.provenance["model_binding"]["model_sha256"].get<std::string>()
              == expect["model_sha256"].get<std::string>(),
          case_id + ": provenance model sha256");
    check(!result.provenance["runtime"]["runtime_version"]
               .get<std::string>()
               .empty(),
          case_id + ": provenance runtime version");
    check(result.provenance["input"]["band_mapping"]["band_name"]
              .get<std::string>()
              == expect["band_name"].get<std::string>(),
          case_id + ": provenance band mapping");

    bool checksum_diagnostic = false;
    for (const Json& diagnostic : result.diagnostics) {
        if (diagnostic.value("code", std::string())
            == "artifact_checksum_verified") {
            checksum_diagnostic = true;
        }
    }
    check(checksum_diagnostic,
          case_id + ": package artifact checksum diagnostic");

    if (expect.contains("invalid_voxels")) {
        check(result.summary["voxels_nodata"].get<long long>()
                  == expect["invalid_voxels"].get<long long>(),
              case_id + ": nodata voxel count");
        const std::vector<std::uint8_t> mask = read_bytes(result.paths.mask);
        check(mask.size() == classmap.size(), case_id + ": mask size");
        std::size_t invalid = 0;
        for (const std::uint8_t value : mask) {
            if (value == 0) ++invalid;
        }
        check(static_cast<long long>(invalid)
                  == expect["invalid_voxels"].get<long long>(),
              case_id + ": written mask invalid count");
    }

    if (expect.value("all_class_zero", false)) {
        check(std::all_of(classmap.begin(), classmap.end(),
                          [](std::uint8_t v) { return v == 0; }),
              case_id + ": every voxel class 0");
    }
    if (expect.value("all_probability_half", false)) {
        check(std::all_of(probmap.begin(), probmap.end(),
                          [](std::uint16_t bits) {
                              return bits == 0x3800;  // float16 0.5
                          }),
              case_id + ": every probability bit pattern is 0.5");
    }
}

void run_error_case(const Json& test_case) {
    const std::string case_id = test_case["id"].get<std::string>();
    const Json& expect = test_case["expect"];
    const fs::path output_dir = prepare_dir(case_id);
    const Json parameters = task_parameters(test_case, output_dir, false);
    const std::string expected_class = expect["raises"].get<std::string>();
    const std::string fragment = expect["message_contains"].get<std::string>();

    bool threw = false;
    std::string actual_class;
    std::string message;
    try {
        PredictionTaskRuntime runtime(
            prediction_task_request_from_json(parameters));
        runtime.execute();
    } catch (const std::exception& exc) {
        threw = true;
        actual_class = error_class_name(exc);
        message = exc.what();
    }
    check(threw, case_id + ": expected " + expected_class);
    check(actual_class == expected_class,
          case_id + ": error class " + actual_class + " expected "
              + expected_class);
    check(message.find(fragment) != std::string::npos,
          case_id + ": message '" + message + "' must contain '" + fragment
              + "'");
}

void run_cancel_and_resume_case(const Json& test_case) {
    const std::string case_id = test_case["id"].get<std::string>();
    const Json& expect = test_case["expect"];
    const fs::path output_dir = prepare_dir("cancel_resume");
    Json parameters = task_parameters(test_case, output_dir, true);

    // Deterministic cancellation: the worker signals the first progress tick
    // and blocks until a second thread has flipped the cancel flag, so the
    // next tile-group poll always observes it.
    std::promise<void> progress_seen;
    std::promise<void> cancel_done;
    std::atomic<bool> signalled{false};
    std::future<void> cancel_done_future = cancel_done.get_future();
    PredictionTaskRequest request =
        prediction_task_request_from_json(parameters);
    request.options.progress = [&](double, const std::string&) {
        if (!signalled.exchange(true)) {
            progress_seen.set_value();
            cancel_done_future.wait();
        }
    };
    PredictionTaskRuntime runtime(std::move(request));
    std::thread canceller([&runtime, &progress_seen, &cancel_done]() {
        progress_seen.get_future().wait();
        runtime.request_cancel();
        cancel_done.set_value();
    });
    const PredictionTaskResult cancelled = runtime.execute();
    canceller.join();
    check(cancelled.status == PredictionTaskStatus::Cancelled,
          case_id + ": cancelled status");
    check(cancelled.stats.cancelled, case_id + ": stats cancelled");
    check(cancelled.stats.tiles_done < cancelled.stats.tiles_total,
          case_id + ": partial progress");

    // Resume with a fresh runtime over the same work root; the result must
    // equal the uncancelled baseline bit for bit.
    PredictionTaskRuntime resumed(prediction_task_request_from_json(
        task_parameters(test_case, output_dir, true)));
    const PredictionTaskResult finished = resumed.execute();
    check(finished.status == PredictionTaskStatus::Succeeded,
          case_id + ": resumed status");
    const std::vector<std::uint8_t> classmap =
        read_bytes(finished.paths.classmap);
    compare_classmap(expect["classmap"], classmap, case_id);
    const std::vector<std::uint16_t> probmap = read_u16(finished.paths.probmap);
    compare_probmap(expect["probmap_bits"], probmap, case_id);
    compare_summary(expect["summary"], finished.summary, case_id);
}

void run_deterministic_repeat_case(const Json& test_case) {
    const std::string case_id = test_case["id"].get<std::string>();
    const Json& expect = test_case["expect"];
    const fs::path first_dir = prepare_dir(case_id + "-a");
    const fs::path second_dir = prepare_dir(case_id + "-b");
    const PredictionTaskResult first = PredictionTaskRuntime(
        prediction_task_request_from_json(
            task_parameters(test_case, first_dir, true))).execute();
    const PredictionTaskResult second = PredictionTaskRuntime(
        prediction_task_request_from_json(
            task_parameters(test_case, second_dir, true))).execute();
    check(first.succeeded() && second.succeeded(),
          case_id + ": both runs succeeded");
    const std::vector<std::uint8_t> first_classmap =
        read_bytes(first.paths.classmap);
    const std::vector<std::uint8_t> second_classmap =
        read_bytes(second.paths.classmap);
    check(first_classmap == second_classmap,
          case_id + ": identical classmap bytes");
    check(read_u16(first.paths.probmap) == read_u16(second.paths.probmap),
          case_id + ": identical probmap bits");
    check(first.output_descriptor["classmap_sha256"]
              == second.output_descriptor["classmap_sha256"],
          case_id + ": identical descriptor digests");
    compare_classmap(expect["classmap"], first_classmap, case_id);
}

void run_resume_fingerprint_case(const Json& baseline,
                                 const Json& other_case) {
    const std::string case_id = "resume_fingerprint";
    const fs::path output_dir = prepare_dir(case_id);
    const PredictionTaskResult first = PredictionTaskRuntime(
        prediction_task_request_from_json(
            task_parameters(baseline, output_dir, true))).execute();
    check(first.succeeded(), case_id + ": first run");
    const std::vector<std::uint8_t> baseline_classmap =
        read_bytes(first.paths.classmap);

    // Same fingerprint: every tile is skipped and the seeded buffers are
    // returned unchanged.
    const PredictionTaskResult second = PredictionTaskRuntime(
        prediction_task_request_from_json(
            task_parameters(baseline, output_dir, true))).execute();
    check(second.succeeded(), case_id + ": resumed run");
    check(second.stats.tiles_done == 0,
          case_id + ": all tiles skipped on an identical rerun");
    check(read_bytes(second.paths.classmap) == baseline_classmap,
          case_id + ": seeded classmap identical");

    // Different model/classes/tile: the fingerprint must reject the stale
    // buffers, clear the markers and recompute every tile.
    const PredictionTaskResult other = PredictionTaskRuntime(
        prediction_task_request_from_json(
            task_parameters(other_case, output_dir, true))).execute();
    check(other.succeeded(), case_id + ": different-input run");
    check(other.stats.tiles_done == other.stats.tiles_total,
          case_id + ": stale markers cleared on a fingerprint mismatch");
    compare_classmap(other_case["expect"]["classmap"],
                     read_bytes(other.paths.classmap), case_id);
}

void run_dtype_input_case() {
    const std::string case_id = "dtype_input_conversion";
    const std::vector<float> values = {0.5f,  -0.25f, 0.75f, 0.125f,
                                       0.0625f, -0.5f, 1.0f,  0.0f};
    for (const char* model : {"identity_f16in.onnx", "identity_f64in.onnx"}) {
        OnnxRuntimeSession session = OnnxRuntimeSession::open_file(
            (fixture_root() / "models" / model).string());
        SessionBatch batch;
        batch.n = 1;
        batch.d = 2;
        batch.h = 2;
        batch.w = 2;
        batch.data = values;
        const SessionOutput out = session.run(batch);
        check(out.ndim == 5 && out.n == 1 && out.c == 1 && out.d == 2
                  && out.h == 2 && out.w == 2,
              std::string(case_id) + ": " + model + " output shape");
        check(out.data.size() == values.size(),
              std::string(case_id) + ": " + model + " output size");
        for (std::size_t i = 0;
             i < out.data.size() && i < values.size(); ++i) {
            check(std::abs(out.data[i] - values[i]) <= 1e-6f,
                  std::string(case_id) + ": " + model + " value "
                      + std::to_string(i));
        }
    }
}

class RecordingSink final : public IPredictionTaskSink {
public:
    int started = 0;
    int progress = 0;
    int finished = 0;
    int failed = 0;

    void on_started(const Json&) override { ++started; }
    void on_progress(const Json&) override { ++progress; }
    void on_finished(const Json&) override { ++finished; }
    void on_failed(const Json&) override { ++failed; }
};

void run_workflow_sink_case(const Json& test_case) {
    const std::string case_id = "workflow_sink";
    RecordingSink sink;
    const Json result = PredictionWorkflowNode::run_observed(
        task_parameters(test_case, prepare_dir(case_id), true), &sink);
    check(result["status"] == "succeeded", case_id + ": status");
    check(sink.started == 1, case_id + ": started notified");
    check(sink.progress >= 1, case_id + ": progress notified");
    check(sink.finished == 1 && sink.failed == 0,
          case_id + ": finished notified");

    // The workflow-engine overload bridges a CancelToken: a pre-cancelled
    // run returns the cancelled descriptor instead of throwing.
    const Json cancelled = PredictionWorkflowNode::run(
        task_parameters(test_case, prepare_dir(case_id + "-cancel"), true),
        []() { return true; }, {});
    check(cancelled["status"] == "cancelled",
          case_id + ": cancel overload");
}

void run_workflow_node_case(const Json& test_case,
                            const std::string& output_dir) {
    const std::string case_id = "workflow_node_descriptor";
    const Json descriptor = PredictionWorkflowNode::descriptor();
    check(descriptor["id"] == "prediction.tiled_onnx",
          case_id + ": node id");
    check(descriptor["deterministic"].get<bool>(),
          case_id + ": deterministic flag");
    Json parameters = task_parameters(test_case, output_dir, true);
    const Json result = PredictionWorkflowNode::run(parameters);
    check(result["status"] == "succeeded", case_id + ": node run status");
    check(result["outputs"]["classmap_sha256"].is_string(),
          case_id + ": node outputs descriptor");
    check(result["output_version"]["kind"] == "pwb-prediction-result",
          case_id + ": output version kind");
    check(result["output_version"]["stage"] == "derived",
          case_id + ": output version stage");
    check(result["output_version"]["asset_name"]
              .get<std::string>()
              .find("-prediction") != std::string::npos,
          case_id + ": output version asset name");
    check(result["output_version"]["map_layers"].is_array(),
          case_id + ": catalog seam map layers");
    check(result["spatial_result"]["result_summary"]["spatial"]["grid"]
              .is_object(),
          case_id + ": spatial envelope grid");

    const std::vector<MapLayerDescriptor> layers = prediction_map_layers(
        result["outputs"]);
    check(layers.size() == 2, case_id + ": classmap + probmap layers");
    check(layers.size() >= 1 && layers[0].kind == "classmap",
          case_id + ": first layer is the class map");
    if (!layers.empty()) {
        check(layers[0].shape == Tile3{10, 12, 9},
              case_id + ": layer shape");
        check(layers[0].dtype == "uint8", case_id + ": layer dtype");
        check(layers[0].has_geotransform
                  && layers[0].geotransform[1] == 25.0,
              case_id + ": layer geotransform");
        check(layers[0].crs == "EPSG:32650", case_id + ": layer crs");
    }
    check(prediction_map_layers(Json::object()).empty(),
          case_id + ": no layers for an empty descriptor");
}

void run_availability_case() {
    std::string error;
    const bool available = onnx_runtime_available(&error);
    check(available, "onnx runtime library available: " + error);
    if (available) {
        check(!onnx_runtime_version().empty(), "onnx runtime version string");
        check(!onnx_runtime_library_path().empty(),
              "onnx runtime library path resolved");
    }
}

}  // namespace

int main() {
    std::cout << "prediction.runtime oracle fixture: " << PWB_RUNTIME_FIXTURE
              << "\n";
    run_availability_case();

    const Json fixture = load_fixture();
    for (const Json& test_case : fixture["cases"]) {
        try {
            run_success_case(test_case);
        } catch (const std::exception& exc) {
            check(false, std::string("case ") + test_case["id"].get<std::string>()
                             + " threw: " + exc.what());
        }
    }
    for (const Json& test_case : fixture["error_cases"]) {
        try {
            run_error_case(test_case);
        } catch (const std::exception& exc) {
            check(false, std::string("error case ")
                             + test_case["id"].get<std::string>()
                             + " harness threw: " + exc.what());
        }
    }

    // C++-only closures over the baseline oracle case.
    const Json& baseline = fixture["cases"][0];
    run_comparator_self_check(baseline);
    run_cancel_and_resume_case(baseline);
    // Nodata runs persist a validity mask; cancellation + resume must seed
    // both the fused buffers and the mask so the resumed summary matches.
    const Json* nodata_case = nullptr;
    for (const Json& test_case : fixture["cases"]) {
        if (test_case["id"].get<std::string>() == "run_nodata_mask") {
            nodata_case = &test_case;
            break;
        }
    }
    check(nodata_case != nullptr, "fixture case run_nodata_mask present");
    if (nodata_case != nullptr) {
        run_cancel_and_resume_case(*nodata_case);
    }
    run_deterministic_repeat_case(baseline);
    run_resume_fingerprint_case(baseline, fixture["cases"][1]);
    run_dtype_input_case();
    run_workflow_node_case(baseline, prepare_dir("workflow-node").string());
    run_workflow_sink_case(baseline);

    std::cout << (g_failures == 0 ? "OK" : "FAILED") << ": " << g_checks
              << " checks, " << g_failures << " failures\n";
    return g_failures == 0 ? 0 : 1;
}

